import{a as e,c as t,i as n,l as r,s as i,t as a}from"./app-B8uz0aqq.js";var o=JSON.parse(`{"path":"/qa/q28-kbengine-registry-actor-transport.html","title":"Q28: KBEngine 是否存在注册中心？CellApp 如何部署和通信？Actor 模型适用吗？","lang":"en-US","frontmatter":{},"filePathRelative":"qa/q28-kbengine-registry-actor-transport.md","git":{"createdTime":1773965296000,"updatedTime":1773965296000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":1}]}}`),s={name:`q28-kbengine-registry-actor-transport.md`};function c(a,o,s,c,l,u){let d=r(`Mermaid`);return t(),n(`div`,null,[o[0]||=e(`<h1 id="q28-kbengine-是否存在注册中心-cellapp-如何部署和通信-actor-模型适用吗" tabindex="-1"><a class="header-anchor" href="#q28-kbengine-是否存在注册中心-cellapp-如何部署和通信-actor-模型适用吗"><span>Q28: KBEngine 是否存在注册中心？CellApp 如何部署和通信？Actor 模型适用吗？</span></a></h1><h2 id="问题分析" tabindex="-1"><a class="header-anchor" href="#问题分析"><span>问题分析</span></a></h2><p>本题考察对 KBEngine/Apollo 内部通信架构的深入理解：</p><ul><li>服务注册与发现机制</li><li>CellApp 的部署策略</li><li>进程间通信方式</li><li>Actor 模型在游戏服务器中的应用</li></ul><hr><h2 id="一、服务注册中心" tabindex="-1"><a class="header-anchor" href="#一、服务注册中心"><span>一、服务注册中心</span></a></h2><h3 id="kbengine-的注册机制" tabindex="-1"><a class="header-anchor" href="#kbengine-的注册机制"><span>KBEngine 的注册机制</span></a></h3><p><strong>CellAppMgr 就是注册中心</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                        KBEngine 架构                            │</span>
<span class="line">├─────────────────────────────────────────────────────────────────┤</span>
<span class="line">│                                                                 │</span>
<span class="line">│  ┌──────────────┐         ┌──────────────┐                    │</span>
<span class="line">│  │  LoginApp    │         │   DBMgr      │                    │</span>
<span class="line">│  └──────┬───────┘         └──────┬───────┘                    │</span>
<span class="line">│         │                        │                             │</span>
<span class="line">│         ▼                        ▼                             │</span>
<span class="line">│  ┌──────────────────────────────────────────────┐            │</span>
<span class="line">│  │            CellAppMgr (注册中心)               │            │</span>
<span class="line">│  │  - 维护所有 CellApp 的地址信息                  │            │</span>
<span class="line">│  │  - 负责空间分配                                │            │</span>
<span class="line">│  │  - Entity 位置注册表                           │            │</span>
<span class="line">│  └──────────────────────────────────────────────┘            │</span>
<span class="line">│         │                        │                             │</span>
<span class="line">│    ┌────┴────┐            ┌─────┴─────┐                         │</span>
<span class="line">│    ▼         ▼            ▼           ▼                         │</span>
<span class="line">│  ┌─────┐  ┌─────┐      ┌─────┐     ┌─────┐                    │</span>
<span class="line">│  |CA 1 |  |CA 2 |      |CA 3 |     |CA 4 |  (CellApp)          │</span>
<span class="line">│  └─────┘  └─────┘      └─────┘     └─────┘                    │</span>
<span class="line">│                                                                 │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>CellAppMgr 的注册中心职责</strong>：</p><table><thead><tr><th>职责</th><th>说明</th></tr></thead><tbody><tr><td><strong>CellApp 注册</strong></td><td>CellApp 启动时向 CellAppMgr 注册</td></tr><tr><td><strong>空间分配</strong></td><td>记录每个 CellApp 负责的空间区域</td></tr><tr><td><strong>Entity 位置</strong></td><td>维护 EntityID → CellApp 的映射</td></tr><tr><td><strong>负载均衡</strong></td><td>新 Entity 创建时选择负载最低的 CellApp</td></tr><tr><td><strong>Entity 查找</strong></td><td>响应 Entity 位置查询请求</td></tr></tbody></table><h3 id="apollo-的改进架构" tabindex="-1"><a class="header-anchor" href="#apollo-的改进架构"><span>Apollo 的改进架构</span></a></h3><p>Apollo 支持更灵活的服务注册/发现：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 支持多种注册中心后端</span></span>
<span class="line"><span class="token keyword">enum</span> <span class="token keyword">class</span> <span class="token class-name">DiscoveryBackend</span> <span class="token punctuation">{</span></span>
<span class="line">    SQLite<span class="token punctuation">,</span>   <span class="token comment">// 本地/测试</span></span>
<span class="line">    Redis<span class="token punctuation">,</span>    <span class="token comment">// 分布式</span></span>
<span class="line">    Etcd<span class="token punctuation">,</span>     <span class="token comment">// 生产环境</span></span>
<span class="line">    Consul    <span class="token comment">// 云原生</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>注册信息示例</strong>：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;server_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;1-2-6-1&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;service&quot;</span><span class="token operator">:</span> <span class="token string">&quot;CellApp&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;host&quot;</span><span class="token operator">:</span> <span class="token string">&quot;10.0.0.5&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;transports&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;protocol&quot;</span><span class="token operator">:</span> <span class="token string">&quot;nng-ipc&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;address&quot;</span><span class="token operator">:</span> <span class="token string">&quot;ipc://cellapp-1.ipc&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;priority&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;attributes&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;locality&quot;</span><span class="token operator">:</span> <span class="token string">&quot;same-host&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;latency&quot;</span><span class="token operator">:</span> <span class="token string">&quot;low&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;protocol&quot;</span><span class="token operator">:</span> <span class="token string">&quot;nng-tcp&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;address&quot;</span><span class="token operator">:</span> <span class="token string">&quot;tcp://10.0.0.5:6100&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;priority&quot;</span><span class="token operator">:</span> <span class="token number">10</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;attributes&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;bandwidth&quot;</span><span class="token operator">:</span> <span class="token string">&quot;high&quot;</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;metadata&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;load&quot;</span><span class="token operator">:</span> <span class="token number">45</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;entity_count&quot;</span><span class="token operator">:</span> <span class="token number">1200</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;space_bounds&quot;</span><span class="token operator">:</span> <span class="token string">&quot;0-1024,0-1024&quot;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="二、cellapp-部署策略" tabindex="-1"><a class="header-anchor" href="#二、cellapp-部署策略"><span>二、CellApp 部署策略</span></a></h2><h3 id="部署方式对比" tabindex="-1"><a class="header-anchor" href="#部署方式对比"><span>部署方式对比</span></a></h3>`,19),i(d,{code:``}),o[1]||=e(`<h3 id="单机多进程部署" tabindex="-1"><a class="header-anchor" href="#单机多进程部署"><span>单机多进程部署</span></a></h3><p><strong>典型配置</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 服务器配置：32核 64GB 内存</span></span>
<span class="line"><span class="token comment"># 部署方案：</span></span>
<span class="line"><span class="token comment"># - 8 个 CellApp 进程</span></span>
<span class="line"><span class="token comment"># - 4 个 BaseApp 进程</span></span>
<span class="line"><span class="token comment"># - 1 个 CellAppMgr</span></span>
<span class="line"><span class="token comment"># - 1 个 BaseAppMgr</span></span>
<span class="line"><span class="token comment"># - 1 个 DBMgr</span></span>
<span class="line"><span class="token comment"># - 1 个 LoginApp</span></span>
<span class="line"><span class="token comment"># - 1 个 GatewayApp</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># CPU 亲和性绑定</span></span>
<span class="line">taskset <span class="token parameter variable">-c</span> <span class="token number">0</span>-3   ./cellapp <span class="token parameter variable">--port</span> <span class="token number">50001</span>  <span class="token comment"># CellApp 1 绑定 CPU 0-3</span></span>
<span class="line">taskset <span class="token parameter variable">-c</span> <span class="token number">4</span>-7   ./cellapp <span class="token parameter variable">--port</span> <span class="token number">50002</span>  <span class="token comment"># CellApp 2 绑定 CPU 4-7</span></span>
<span class="line">taskset <span class="token parameter variable">-c</span> <span class="token number">8</span>-11  ./cellapp <span class="token parameter variable">--port</span> <span class="token number">50003</span>  <span class="token comment"># CellApp 3 绑定 CPU 8-11</span></span>
<span class="line">taskset <span class="token parameter variable">-c</span> <span class="token number">12</span>-15 ./cellapp <span class="token parameter variable">--port</span> <span class="token number">50004</span>  <span class="token comment"># CellApp 4 绑定 CPU 12-15</span></span>
<span class="line">taskset <span class="token parameter variable">-c</span> <span class="token number">16</span>-19 ./cellapp <span class="token parameter variable">--port</span> <span class="token number">50005</span>  <span class="token comment"># CellApp 5 绑定 CPU 16-19</span></span>
<span class="line">taskset <span class="token parameter variable">-c</span> <span class="token number">20</span>-23 ./cellapp <span class="token parameter variable">--port</span> <span class="token number">50006</span>  <span class="token comment"># CellApp 6 绑定 CPU 20-23</span></span>
<span class="line">taskset <span class="token parameter variable">-c</span> <span class="token number">24</span>-27 ./cellapp <span class="token parameter variable">--port</span> <span class="token number">50007</span>  <span class="token comment"># CellApp 7 绑定 CPU 24-27</span></span>
<span class="line">taskset <span class="token parameter variable">-c</span> <span class="token number">28</span>-31 ./cellapp <span class="token parameter variable">--port</span> <span class="token number">50008</span>  <span class="token comment"># CellApp 8 绑定 CPU 28-31</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>CPU 亲和性配置</strong>：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// Linux 设置 CPU 亲和性</span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;sched.h&gt;</span></span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">void</span> <span class="token function">set_cpu_affinity</span><span class="token punctuation">(</span><span class="token keyword">int</span> core_id<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    cpu_set_t cpuset<span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">CPU_ZERO</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>cpuset<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">CPU_SET</span><span class="token punctuation">(</span>core_id<span class="token punctuation">,</span> <span class="token operator">&amp;</span>cpuset<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">pthread_setaffinity_np</span><span class="token punctuation">(</span><span class="token function">pthread_self</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token keyword">sizeof</span><span class="token punctuation">(</span>cpu_set_t<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>cpuset<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 设置 CPU 亲和性和线程数</span></span>
<span class="line"><span class="token keyword">void</span> <span class="token function">configure_thread_pool</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 获取 CPU 核心数</span></span>
<span class="line">    <span class="token keyword">int</span> num_cores <span class="token operator">=</span> std<span class="token double-colon punctuation">::</span>thread<span class="token double-colon punctuation">::</span><span class="token function">hardware_concurrency</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 网络线程：绑定到核心 0</span></span>
<span class="line">    <span class="token function">set_cpu_affinity</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 逻辑线程：分散到其他核心</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> num_cores <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">;</span> <span class="token operator">++</span>i<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">set_cpu_affinity</span><span class="token punctuation">(</span>i <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="多机分布式部署" tabindex="-1"><a class="header-anchor" href="#多机分布式部署"><span>多机分布式部署</span></a></h3><p><strong>典型集群配置</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                        游戏服务器集群                            │</span>
<span class="line">├─────────────────────────────────────────────────────────────────┤</span>
<span class="line">│                                                                 │</span>
<span class="line">│  ┌──────────────────┐  ┌──────────────────┐                   │</span>
<span class="line">│  │   机器 A: 登录层  │  │  机器 B: 网关层   │                   │</span>
<span class="line">│  │  ┌────────────┐  │  │  ┌────────────┐  │                   │</span>
<span class="line">│  │  │ LoginApp 1 │  │  │  │ Gateway 1  │  │                   │</span>
<span class="line">│  │  │ LoginApp 2 │  │  │  │ Gateway 2  │  │                   │</span>
<span class="line">│  │  └────────────┘  │  │  └────────────┘  │                   │</span>
<span class="line">│  └──────────────────┘  └──────────────────┘                   │</span>
<span class="line">│                                                                 │</span>
<span class="line">│  ┌──────────────────┐  ┌──────────────────┐                   │</span>
<span class="line">│  │  机器 C: 空间层   │  │  机器 D: 空间层   │                   │</span>
<span class="line">│  │  ┌────────────┐  │  │  ┌────────────┐  │                   │</span>
<span class="line">│  │  │CellApp 1-4 │  │  │  │CellApp 5-8 │  │                   │</span>
<span class="line">│  │  │(新区)     │  │  │  │(老区)     │  │                   │</span>
<span class="line">│  │  └────────────┘  │  │  └────────────┘  │                   │</span>
<span class="line">│  └──────────────────┘  └──────────────────┘                   │</span>
<span class="line">│                                                                 │</span>
<span class="line">│  ┌──────────────────┐  ┌──────────────────┐                   │</span>
<span class="line">│  │  机器 E: 逻辑层   │  │  机器 F: 数据层   │                   │</span>
<span class="line">│  │  ┌────────────┐  │  │  ┌────────────┐  │                   │</span>
<span class="line">│  │  │BaseApp 1-4 │  │  │  │   DBMgr    │  │                   │</span>
<span class="line">│  │  │CellMgr     │  │  │  │  BaseMgr   │  │                   │</span>
<span class="line">│  │  │BaseMgr     │  │  │  │  Redis     │  │                   │</span>
<span class="line">│  │  └────────────┘  │  │  └────────────┘  │                   │</span>
<span class="line">│  └──────────────────┘  └──────────────────┘                   │</span>
<span class="line">│                                                                 │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="三、cellapp-通信机制" tabindex="-1"><a class="header-anchor" href="#三、cellapp-通信机制"><span>三、CellApp 通信机制</span></a></h2><h3 id="通信方式对比" tabindex="-1"><a class="header-anchor" href="#通信方式对比"><span>通信方式对比</span></a></h3><table><thead><tr><th>通信方式</th><th>延迟</th><th>带宽</th><th>适用场景</th><th>实现</th></tr></thead><tbody><tr><td><strong>共享内存</strong></td><td>~1μs</td><td>极高</td><td>同进程</td><td>自定义环形缓冲区</td></tr><tr><td><strong>Unix Socket</strong></td><td>~10μs</td><td>高</td><td>同机</td><td>NNG IPC</td></tr><tr><td><strong>TCP (回环)</strong></td><td>~50μs</td><td>高</td><td>同机/跨机</td><td>NNG TCP</td></tr><tr><td><strong>TCP (跨机)</strong></td><td>~100-500μs</td><td>中</td><td>跨机</td><td>NNG TCP</td></tr></tbody></table><h3 id="nng-通信框架" tabindex="-1"><a class="header-anchor" href="#nng-通信框架"><span>NNG 通信框架</span></a></h3><p>Apollo 使用 <strong>NNG (Nanomsg Next Gen)</strong> 作为底层通信框架：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// NNG 支持的协议模式</span></span>
<span class="line"><span class="token keyword">namespace</span> apollo<span class="token double-colon punctuation">::</span>protocol <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 1. Pair 模式（点对点）</span></span>
<span class="line">NngSocket pair_socket<span class="token punctuation">;</span></span>
<span class="line"><span class="token function">nng_pair0_open</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>pair_socket<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 2. Req/Rep 模式（请求响应）</span></span>
<span class="line">NngSocket req_socket<span class="token punctuation">;</span></span>
<span class="line"><span class="token function">nng_req0_open</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>req_socket<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 3. Pub/Sub 模式（发布订阅）</span></span>
<span class="line">NngSocket pub_socket<span class="token punctuation">;</span></span>
<span class="line"><span class="token function">nng_pub0_open</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>pub_socket<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 4. Bus 模式（多对多）</span></span>
<span class="line">NngSocket bus_socket<span class="token punctuation">;</span></span>
<span class="line"><span class="token function">nng_bus0_open</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>bus_socket<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token punctuation">}</span> <span class="token comment">// namespace apollo::protocol</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>传输优先级自动选择</strong>：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">struct</span> <span class="token class-name">TransportEndpoint</span> <span class="token punctuation">{</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>string protocol<span class="token punctuation">;</span>    <span class="token comment">// &quot;nng-tcp&quot;, &quot;nng-ipc&quot;, &quot;shm&quot;</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>string address<span class="token punctuation">;</span>     <span class="token comment">// &quot;tcp://host:port&quot;, &quot;ipc://path&quot;</span></span>
<span class="line">    <span class="token keyword">int</span> priority <span class="token operator">=</span> <span class="token number">100</span><span class="token punctuation">;</span>      <span class="token comment">// 越小越优先</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 自动选择最佳传输</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>string <span class="token function">getBestAddress</span><span class="token punctuation">(</span><span class="token keyword">const</span> std<span class="token double-colon punctuation">::</span>string<span class="token operator">&amp;</span> local_host<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>protocol <span class="token operator">==</span> <span class="token string">&quot;shm&quot;</span> <span class="token operator">&amp;&amp;</span> <span class="token function">isSameProcess</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> address<span class="token punctuation">;</span>  <span class="token comment">// 共享内存优先</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>protocol <span class="token operator">==</span> <span class="token string">&quot;nng-ipc&quot;</span> <span class="token operator">&amp;&amp;</span> <span class="token function">isSameHost</span><span class="token punctuation">(</span>local_host<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> address<span class="token punctuation">;</span>  <span class="token comment">// IPC 其次</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">return</span> tcp_address<span class="token punctuation">;</span>  <span class="token comment">// TCP 最后</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="共享内存通道" tabindex="-1"><a class="header-anchor" href="#共享内存通道"><span>共享内存通道</span></a></h3><p>Apollo 实现了零拷贝的共享内存通信：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">class</span> <span class="token class-name">SharedMemoryRingBuffer</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">struct</span> <span class="token class-name">Header</span> <span class="token punctuation">{</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>atomic<span class="token operator">&lt;</span>size_t<span class="token operator">&gt;</span> writePos<span class="token punctuation">{</span><span class="token number">0</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>atomic<span class="token operator">&lt;</span>size_t<span class="token operator">&gt;</span> readPos<span class="token punctuation">{</span><span class="token number">0</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>atomic<span class="token operator">&lt;</span>size_t<span class="token operator">&gt;</span> count<span class="token punctuation">{</span><span class="token number">0</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">        size_t capacity<span class="token punctuation">{</span><span class="token number">0</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">uint32_t</span> magic<span class="token punctuation">{</span><span class="token number">0</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 零拷贝写入</span></span>
<span class="line">    <span class="token keyword">void</span><span class="token operator">*</span> <span class="token function">allocate</span><span class="token punctuation">(</span>size_t size<span class="token punctuation">,</span> <span class="token keyword">uint32_t</span> type <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">commit</span><span class="token punctuation">(</span>size_t size<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 零拷贝读取</span></span>
<span class="line">    <span class="token keyword">struct</span> <span class="token class-name">ReadResult</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">const</span> <span class="token keyword">void</span><span class="token operator">*</span> data<span class="token punctuation">;</span>  <span class="token comment">// 直接指向共享内存</span></span>
<span class="line">        size_t size<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">uint32_t</span> type<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">bool</span> <span class="token function">read</span><span class="token punctuation">(</span>ReadResult<span class="token operator">&amp;</span> result<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">consume</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>FlatBuffers 零拷贝集成</strong>：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">class</span> <span class="token class-name">FlatBufferChannel</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 发送：直接在共享内存中构建 FlatBuffer</span></span>
<span class="line">    <span class="token keyword">template</span><span class="token operator">&lt;</span><span class="token keyword">typename</span> <span class="token class-name">BuilderFunc</span><span class="token operator">&gt;</span></span>
<span class="line">    <span class="token keyword">bool</span> <span class="token function">send</span><span class="token punctuation">(</span>BuilderFunc builder<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">auto</span><span class="token operator">*</span> buf <span class="token operator">=</span> ringBuffer_<span class="token operator">-&gt;</span><span class="token function">allocate</span><span class="token punctuation">(</span>size<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">// 在共享内存中直接构建，无需拷贝</span></span>
<span class="line">        <span class="token function">builder</span><span class="token punctuation">(</span>fbb<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span><span class="token function">memcpy</span><span class="token punctuation">(</span>buf<span class="token punctuation">,</span> fbb<span class="token punctuation">.</span><span class="token function">GetBufferPointer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> fbb<span class="token punctuation">.</span><span class="token function">GetSize</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        ringBuffer_<span class="token operator">-&gt;</span><span class="token function">commit</span><span class="token punctuation">(</span>fbb<span class="token punctuation">.</span><span class="token function">GetSize</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 接收：直接从共享内存读取，无需拷贝</span></span>
<span class="line">    <span class="token keyword">template</span><span class="token operator">&lt;</span><span class="token keyword">typename</span> <span class="token class-name">T</span><span class="token operator">&gt;</span></span>
<span class="line">    <span class="token keyword">const</span> T<span class="token operator">*</span> <span class="token function">receiveAs</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        Message msg<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token function">receive</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">nullptr</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">// 直接返回指向共享内存的指针</span></span>
<span class="line">        <span class="token keyword">return</span> flatbuffers<span class="token double-colon punctuation">::</span><span class="token generic-function"><span class="token function">GetRoot</span><span class="token generic class-name"><span class="token operator">&lt;</span>T<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span>msg<span class="token punctuation">.</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="四、actor-模型应用" tabindex="-1"><a class="header-anchor" href="#四、actor-模型应用"><span>四、Actor 模型应用</span></a></h2><h3 id="actor-模型与-cellapp" tabindex="-1"><a class="header-anchor" href="#actor-模型与-cellapp"><span>Actor 模型与 CellApp</span></a></h3>`,25),i(d,{code:``}),o[2]||=e(`<h3 id="actor-模型适用性分析" tabindex="-1"><a class="header-anchor" href="#actor-模型适用性分析"><span>Actor 模型适用性分析</span></a></h3><table><thead><tr><th>特性</th><th>Actor 模型</th><th>说明</th></tr></thead><tbody><tr><td><strong>并发模型</strong></td><td>消息传递</td><td>每个玩家/NPC 一个 Actor</td></tr><tr><td><strong>状态隔离</strong></td><td>✅ 天然支持</td><td>Actor 状态互不影响</td></tr><tr><td><strong>位置透明</strong></td><td>✅ 支持</td><td>本地/远程 Actor 统一接口</td></tr><tr><td><strong>容错性</strong></td><td>✅ Let It Crash</td><td>Actor 崩溃可自动重启</td></tr><tr><td><strong>热更新</strong></td><td>✅ 支持</td><td>Actor 代码可热替换</td></tr></tbody></table><h3 id="caf-框架对比" tabindex="-1"><a class="header-anchor" href="#caf-框架对比"><span>CAF 框架对比</span></a></h3><p><strong>CAF (C++ Actor Framework)</strong> 是成熟的 Actor 框架：</p><table><thead><tr><th>特性</th><th>CAF</th><th>Apollo Actor</th></tr></thead><tbody><tr><td><strong>同机通信</strong></td><td>共享内存</td><td>共享内存 + NNG IPC</td></tr><tr><td><strong>跨机通信</strong></td><td>BASP 协议</td><td>NNG TCP</td></tr><tr><td><strong>序列化</strong></td><td>自定义</td><td>FlatBuffers/JSON</td></tr><tr><td><strong>服务发现</strong></td><td>内置</td><td>可插拔（SQLite/Redis/Etcd）</td></tr><tr><td><strong>监控</strong></td><td>内置</td><td>可插拔</td></tr></tbody></table><p><strong>CAF 通信架构</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                         CAF 通信层                              │</span>
<span class="line">├─────────────────────────────────────────────────────────────────┤</span>
<span class="line">│                                                                 │</span>
<span class="line">│  ┌─────────────┐                                               │</span>
<span class="line">│  │  Application│                                              │</span>
<span class="line">│  │   (Actor)   │                                              │</span>
<span class="line">│  └──────┬──────┘                                               │</span>
<span class="line">│         │                                                       │</span>
<span class="line">│         ▼                                                       │</span>
<span class="line">│  ┌─────────────┐    ┌─────────────┐    ┌─────────────┐        │</span>
<span class="line">│  │   Default   │    │   Forward   │    │   BASP      │        │</span>
<span class="line">│  │  Multiplexer│───▶│ing Actor    │───▶│  Protocol   │        │</span>
<span class="line">│  └──────┬──────┘    └─────────────┘    └──────┬──────┘        │</span>
<span class="line">│         │                                      │               │</span>
<span class="line">│         ▼                                      ▼               │</span>
<span class="line">│  ┌─────────────────────────────────────────────────────────┐   │</span>
<span class="line">│  │                   Transport Layer                       │   │</span>
<span class="line">│  │  ┌─────────┐  ┌─────────┐  ┌─────────┐  ┌─────────┐   │   │</span>
<span class="line">│  │  │  SHM    │  │ IPC     │  │ TCP     │  │ UDP     │   │   │</span>
<span class="line">│  │  └─────────┘  └─────────┘  └─────────┘  └─────────┘   │   │</span>
<span class="line">│  └─────────────────────────────────────────────────────────┘   │</span>
<span class="line">│                                                                 │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="apollo-actor-实现" tabindex="-1"><a class="header-anchor" href="#apollo-actor-实现"><span>Apollo Actor 实现</span></a></h3><p><strong>位置透明的消息传递</strong>：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">class</span> <span class="token class-name">ActorRef</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token comment">// 发送消息（自动选择最佳传输）</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">tell</span><span class="token punctuation">(</span><span class="token keyword">const</span> Message<span class="token operator">&amp;</span> msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 请求-响应</span></span>
<span class="line">    <span class="token keyword">template</span><span class="token operator">&lt;</span><span class="token keyword">typename</span> <span class="token class-name">Response</span><span class="token operator">&gt;</span></span>
<span class="line">    Future<span class="token operator">&lt;</span>Response<span class="token operator">&gt;</span> <span class="token function">ask</span><span class="token punctuation">(</span><span class="token keyword">const</span> Message<span class="token operator">&amp;</span> msg<span class="token punctuation">,</span> Duration timeout<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">private</span><span class="token operator">:</span></span>
<span class="line">    ActorPath path_<span class="token punctuation">;</span>              <span class="token comment">// &quot;sys://game-server/cellapp-1/player-123&quot;</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>shared_ptr<span class="token operator">&lt;</span>MessageBus<span class="token operator">&gt;</span> bus_<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">MessageBus</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token comment">// 根据目标地址自动选择传输</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">send</span><span class="token punctuation">(</span><span class="token keyword">const</span> ActorPath<span class="token operator">&amp;</span> target<span class="token punctuation">,</span> <span class="token keyword">const</span> Message<span class="token operator">&amp;</span> msg<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>target<span class="token punctuation">.</span><span class="token function">isLocal</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 邮箱直接投递</span></span>
<span class="line">            local_mailbox_<span class="token operator">-&gt;</span><span class="token function">enqueue</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>target<span class="token punctuation">.</span><span class="token function">isSameHost</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 共享内存或 IPC</span></span>
<span class="line">            shm_channel_<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// TCP</span></span>
<span class="line">            tcp_channel_<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Actor 与 Entity 的对应关系</strong>：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 每个 Entity 对应一个 Actor</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">EntityActor</span> <span class="token operator">:</span> <span class="token base-clause"><span class="token keyword">public</span> <span class="token class-name">Actor</span></span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">protected</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">receive</span><span class="token punctuation">(</span><span class="token keyword">const</span> Message<span class="token operator">&amp;</span> msg<span class="token punctuation">)</span> <span class="token keyword">override</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>msg<span class="token punctuation">.</span><span class="token generic-function"><span class="token function">is</span><span class="token generic class-name"><span class="token operator">&lt;</span>MoveRequest<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">handleMove</span><span class="token punctuation">(</span>msg<span class="token punctuation">.</span><span class="token generic-function"><span class="token function">as</span><span class="token generic class-name"><span class="token operator">&lt;</span>MoveRequest<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>msg<span class="token punctuation">.</span><span class="token generic-function"><span class="token function">is</span><span class="token generic class-name"><span class="token operator">&lt;</span>AttackRequest<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">handleAttack</span><span class="token punctuation">(</span>msg<span class="token punctuation">.</span><span class="token generic-function"><span class="token function">as</span><span class="token generic class-name"><span class="token operator">&lt;</span>AttackRequest<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>msg<span class="token punctuation">.</span><span class="token generic-function"><span class="token function">is</span><span class="token generic class-name"><span class="token operator">&lt;</span>GhostSync<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">handleGhostSync</span><span class="token punctuation">(</span>msg<span class="token punctuation">.</span><span class="token generic-function"><span class="token function">as</span><span class="token generic class-name"><span class="token operator">&lt;</span>GhostSync<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">private</span><span class="token operator">:</span></span>
<span class="line">    Entity<span class="token operator">*</span> entity_<span class="token punctuation">;</span>  <span class="token comment">// 关联的游戏实体</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="五、通信优化策略" tabindex="-1"><a class="header-anchor" href="#五、通信优化策略"><span>五、通信优化策略</span></a></h2><h3 id="批量消息合并" tabindex="-1"><a class="header-anchor" href="#批量消息合并"><span>批量消息合并</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">class</span> <span class="token class-name">BatchMessageBus</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token comment">// 批量发送</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">send_batch</span><span class="token punctuation">(</span><span class="token keyword">const</span> std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Message<span class="token operator">&gt;</span><span class="token operator">&amp;</span> msgs<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>msgs<span class="token punctuation">.</span><span class="token function">size</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> batch_threshold_<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 合并成一个批量消息</span></span>
<span class="line">            BatchMessage batch<span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> <span class="token keyword">auto</span><span class="token operator">&amp;</span> msg <span class="token operator">:</span> msgs<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                batch<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            channel_<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span>batch<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 单独发送</span></span>
<span class="line">            <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> <span class="token keyword">auto</span><span class="token operator">&amp;</span> msg <span class="token operator">:</span> msgs<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                channel_<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="背压控制" tabindex="-1"><a class="header-anchor" href="#背压控制"><span>背压控制</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">class</span> <span class="token class-name">Mailbox</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token comment">// 背压检测</span></span>
<span class="line">    <span class="token keyword">bool</span> <span class="token function">isUnderBackpressure</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">const</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> queue_<span class="token punctuation">.</span><span class="token function">size</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&gt;</span> high_water_mark_<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 限流</span></span>
<span class="line">    <span class="token keyword">bool</span> <span class="token function">try_enqueue</span><span class="token punctuation">(</span><span class="token keyword">const</span> Message<span class="token operator">&amp;</span> msg<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">isUnderBackpressure</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 拒绝或延迟</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        queue_<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="零拷贝优化" tabindex="-1"><a class="header-anchor" href="#零拷贝优化"><span>零拷贝优化</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// FlatBuffers 零拷贝示例</span></span>
<span class="line"><span class="token keyword">void</span> <span class="token function">send_position_update</span><span class="token punctuation">(</span><span class="token keyword">const</span> std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>PlayerPosition<span class="token operator">&gt;</span><span class="token operator">&amp;</span> positions<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    flatbuffers<span class="token double-colon punctuation">::</span>FlatBufferBuilder fbb<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 直接在 FlatBuffer 中构建数组</span></span>
<span class="line">    <span class="token keyword">auto</span> position_vec <span class="token operator">=</span> fbb<span class="token punctuation">.</span><span class="token function">CreateVector</span><span class="token punctuation">(</span>positions<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">auto</span> update <span class="token operator">=</span> <span class="token function">CreatePositionUpdate</span><span class="token punctuation">(</span>fbb<span class="token punctuation">,</span> position_vec<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    fbb<span class="token punctuation">.</span><span class="token function">Finish</span><span class="token punctuation">(</span>update<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 零拷贝发送到共享内存</span></span>
<span class="line">    shm_channel_<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span>fbb<span class="token punctuation">.</span><span class="token function">GetBufferPointer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> fbb<span class="token punctuation">.</span><span class="token function">GetSize</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="六、部署建议" tabindex="-1"><a class="header-anchor" href="#六、部署建议"><span>六、部署建议</span></a></h2><h3 id="小规模部署-1000-人" tabindex="-1"><a class="header-anchor" href="#小规模部署-1000-人"><span>小规模部署（&lt; 1000 人）</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">单机配置：</span>
<span class="line">- 4 核 8GB</span>
<span class="line">- 1 个 CellApp</span>
<span class="line">- 1 个 BaseApp</span>
<span class="line">- 1 个 DBMgr</span>
<span class="line">- 1 个 Gateway</span>
<span class="line">- 1 个 CellAppMgr/BaseAppMgr</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="中等规模-1000-5000-人" tabindex="-1"><a class="header-anchor" href="#中等规模-1000-5000-人"><span>中等规模（1000-5000 人）</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">单机多进程：</span>
<span class="line">- 16 核 32GB</span>
<span class="line">- 4 个 CellApp（各绑 4 核）</span>
<span class="line">- 2 个 BaseApp</span>
<span class="line">- 1 个 DBMgr</span>
<span class="line">- 2 个 Gateway</span>
<span class="line">- 1 个 CellAppMgr/BaseAppMgr</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="大规模-5000-人" tabindex="-1"><a class="header-anchor" href="#大规模-5000-人"><span>大规模（&gt; 5000 人）</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">集群部署：</span>
<span class="line">- 登录服务器（2 台）：LoginApp 集群</span>
<span class="line">- 网关服务器（4 台）：Gateway 集群</span>
<span class="line">- 游戏服务器（8 台）：CellApp + BaseApp 混合部署</span>
<span class="line">- 数据服务器（2 台）：DBMgr + Redis + 基础服务管理器</span>
<span class="line">- Etcd 集群（3 台）：服务注册中心</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="七、参考资料" tabindex="-1"><a class="header-anchor" href="#七、参考资料"><span>七、参考资料</span></a></h2><ul><li><a href="https://nanomsg.github.io/nng/" target="_blank" rel="noopener noreferrer">NNG (Nanomsg Next Gen)</a></li><li><a href="https://www.actor-framework.io/" target="_blank" rel="noopener noreferrer">CAF (C++ Actor Framework)</a></li><li><a href="https://github.com/kbengine/kbengine" target="_blank" rel="noopener noreferrer">KBEngine 架构文档</a></li><li><a href="https://google.github.io/flatbuffers/" target="_blank" rel="noopener noreferrer">FlatBuffers 零拷贝序列化</a></li><li><a href="https://man7.org/linux/man-pages/man7/shm_overview.7.html" target="_blank" rel="noopener noreferrer">共享内存 IPC 设计</a></li></ul>`,31)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};